'use client';

import React, { useCallback, useEffect, useState, useRef, FormEvent, ChangeEvent } from "react";
import { useRouter, useParams } from "next/navigation";
import { useFirebase } from "@/context/FirebaseContext";
import AttachFileIcon from "@mui/icons-material/AttachFile";
import SendIcon from "@mui/icons-material/Send";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import { CircularProgress, LinearProgress } from "@mui/material";
import { useTheme } from "@/context/ThemeContext";

const MessageInput: React.FC = () => {
  const [message, setMessage] = useState<string>("");
  const [file, setFile] = useState<File | null>(null);
  const [uploadProgress, setUploadProgress] = useState<number>(0);
  const [username, setUsername] = useState<string>("");

  const params = useParams();
  const roomId = params?.roomId as string;
  const firebase = useFirebase();
  const router = useRouter();

  const currentUserId = firebase.getCurrentUserId();
  const [isUploading, setIsUploading] = useState<boolean>(false);
  const { theme } = useTheme();

  const fileInputRef = useRef<HTMLInputElement>(null);

  const getTime = (): string => {
    const now = new Date();
    let hours = now.getHours();
    const minutes = now.getMinutes();
    const meridiem = hours >= 12 ? "PM" : "AM";
    hours = hours % 12 || 12;
    const paddedMinutes = minutes < 10 ? `0${minutes}` : minutes;
    return `${hours}:${paddedMinutes} ${meridiem}`;
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!firebase || !currentUserId || !roomId) return;
    if (!message.trim()) return;

    const time = getTime();

    firebase.sendMessage({
      message,
      id: currentUserId,
      username,
      roomId,
      time,
    });
    setMessage("");
  };

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) setFile(selectedFile);
    e.target.value = "";
  };

  const handleFileShare = () => {
    if (!file || !currentUserId || !roomId) return;

    setIsUploading(true);
    setUploadProgress(0);

    const time = getTime();
    const reader = new FileReader();

    reader.onload = (e) => {
      const fileContent = e.target?.result;
      if (!fileContent) return;

      // Type assertion as sendFile expects ArrayBuffer | Uint8Array | Blob
      // FileReader.result is string | ArrayBuffer. We need ArrayBuffer.
      // We should use readAsArrayBuffer below.

      firebase.sendFile(
        username,
        file.name,
        fileContent as ArrayBuffer,
        roomId,
        time,
        (url) => {
          setIsUploading(false);
          setUploadProgress(0);
          setFile(null);

          firebase.sendMessage({
            message: file.name,
            id: currentUserId,
            username,
            roomId,
            time,
            download: url,
          });
        },
        (progressEvent) => {
          if (progressEvent.lengthComputable) {
            const percent = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            setUploadProgress(percent);
          }
        }
      );
    };

    reader.onerror = () => {
      setIsUploading(false);
      setUploadProgress(0);
      setFile(null);
      alert("Failed to read file. Please try again.");
    };

    reader.readAsArrayBuffer(file);
  };

  const handleShareButtonClick = () => {
    if (file) {
      handleFileShare();
    } else {
      fileInputRef.current?.click();
    }
  };

  const fetchUsername = useCallback(() => {
    if (roomId) {
      firebase.getCurrentUserDetails(roomId).then((user) => setUsername(user));
    }
  }, [firebase, roomId]);

  useEffect(() => {
    firebase.onAuthStateChanged((user) => {
      if (!user) {
        router.push("/");
        return;
      }
      fetchUsername();
    });
    // Cleanup if needed, though onAuthStateChanged wrapper currently returns void in Service (should fix, but for now safe)
  }, [firebase, fetchUsername]);

  useEffect(() => {
    if (!roomId) return;
    const kickoutListener = async (_data: any) => {
      // logic here if needed
    };
    const unsubscribe = firebase.subscribeToRoomUsers(roomId, {
      onKick: kickoutListener
    });
    return () => unsubscribe();
  }, [firebase, roomId]);

  return (
    <div
      className={`w-full px-4 sm:px-6 lg:px-20 py-3 backdrop-blur-sm z-20 
    ${theme === "light"
          ? "bg-white border-gray-200"
          : "dark border-gray-700"
        }
    flex items-center gap-3 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] border-t`}
      style={{ minHeight: 70 }}
    >
      <input
        type="file"
        ref={fileInputRef}
        hidden
        onChange={handleFileChange}
        accept="*/*"
      />

      <button
        onClick={handleShareButtonClick}
        disabled={isUploading}
        aria-label={file ? "Upload file" : "Attach file"}
        className={`flex items-center justify-center w-12 h-12 rounded-xl shrink-0 shadow-md border 
      ${theme === "light"
            ? "border-gray-300 hover:bg-gray-100"
            : "border-gray-600 hover:bg-gray-800"
          }
      transition-colors duration-200`}
      >
        {isUploading ? (
          <CircularProgress size={28} />
        ) : file ? (
          <CloudUploadIcon style={{ color: "#007AFF" }} />
        ) : (
          <AttachFileIcon
            style={{ transform: "rotate(45deg)", color: "#007AFF" }}
          />
        )}
      </button>

      <form
        onSubmit={handleSubmit}
        className="flex items-center flex-grow gap-3"
        role="form"
      >
        <input
          type="text"
          placeholder={"Type your message..."}
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          disabled={isUploading}
          className={`flex-grow rounded-xl px-5 py-3 shadow-inner border 
        ${theme === "light"
              ? "border-gray-300 bg-white text-black placeholder-gray-500 focus:ring-blue-400"
              : "border-gray-600 bg-gray-800 text-white placeholder-gray-400 focus:ring-blue-500"
            } 
        focus:outline-none focus:ring-2 transition-colors duration-200`}
        />

        <button
          type="submit"
          disabled={!message.trim() || isUploading}
          className={`w-12 h-12 rounded-full flex items-center justify-center shadow-md transition-colors duration-200 
        ${message.trim() && !isUploading
              ? "bg-blue-600 hover:bg-blue-700"
              : "bg-blue-300 cursor-not-allowed"
            }`}
        >
          <SendIcon
            style={{ width: 26, color: "white", transform: "rotate(-25deg)" }}
          />
        </button>
      </form>

      {isUploading && (
        <div className="absolute bottom-[80px] left-0 right-0 px-6">
          <LinearProgress
            variant="determinate"
            value={uploadProgress}
            className="rounded-full"
            sx={{
              height: 6,
              borderRadius: 3,
              backgroundColor: theme === "dark" ? "#374151" : "#E5E7EB",
              "& .MuiLinearProgress-bar": {
                backgroundColor: "#007AFF",
              },
            }}
          />
          <p
            className={`text-center text-xs mt-1 font-semibold ${theme === "light" ? "text-blue-600" : "text-blue-400"
              }`}
          >
            Uploading {uploadProgress}%
          </p>
        </div>
      )}
    </div>
  );
};

export default MessageInput;
